// Add authentication middleware
const authenticate = require('./middleware/auth');
app.use(authenticate);

// Add rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Add authorization checks
app.get('/users', authenticate, (req, res) => {
  // Only allow users to see their own data or admins to see all
  if (req.user.role !== 'admin' && req.user.id !== req.query.id) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json([...]);
});
```

---

#### 3. **Missing Security Headers** (MEDIUM)
**Location:** `app.js` - No middleware configured  
**Issue:** No security headers are set (no HELMET, CSP, HSTS, X-Frame-Options, etc.)

**Risks:**
- Vulnerable to clickjacking attacks
- Missing security headers leave app exposed to common web vulnerabilities
- No protection against XSS, MIME sniffing, etc.

**Fix:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

---

#### 4. **No Input Validation** (MEDIUM)
**Location:** `app.js` - `/health` and `/users` endpoints  
**Issue:** No validation of query parameters or request bodies

**Risks:**
- Potential injection attacks
- DoS via malformed requests

**Fix:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', [
  query('id').optional().isInt(),
  query('limit').optional().isInt().max(100)
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // ... rest of handler
});
```

---

#### 5. **No Error Handling** (MEDIUM)
**Location:** `app.js` - No error handlers  
**Issue:** No global error handler catches unhandled exceptions or routes

**Risks:**
- Verbose error messages can expose internal structure
- Stack traces could reveal sensitive information
- Application could crash ungracefully

**Fix:**
```javascript
// Add 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Add error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  // Don't expose error details in production
  res.status(500).json({ 
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message 
  });
});
```

---

#### 6. **No CORS Protection** (MEDIUM)
**Location:** `app.js` - CORS not configured  
**Issue:** No CORS policy configured; could be vulnerable to cross-site requests

**Fix:**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true
}));
```

---

#### 7. **Sensitive Data Exposure in Response** (MEDIUM)
**Location:** `app.js` - Line 8  
**Issue:** Timestamp exposed in `/health` endpoint (information disclosure)

**Fix:** Remove unnecessary timestamps or ensure they don't reveal system information

---

#### 8. **Missing HTTPS/TLS** (HIGH)
**Location:** `app.js` - Only HTTP server  
**Issue:** Server doesn't enforce HTTPS, allowing man-in-the-middle attacks

**Fix:**
```javascript
const https = require('https');
const fs = require('fs');
const options = {
  key: fs.readFileSync('private-key.pem'),
  cert: fs.readFileSync('certificate.pem')
};
https.createServer(options, app).listen(3000);
```

