// Secured version of the application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// 1. Security headers with Helmet
app.use(helmet());

// 2. CORS configuration (restrict if needed)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'localhost',
  credentials: true
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// 4. Request validation middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size

// 5. Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 6. Users endpoint with proper error handling
app.get('/users', (req, res, next) => {
  try {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    next(error);
  }
});

// 7. Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const message = isDevelopment ? err.message : 'Internal Server Error';

  res.status(err.status || 500).json({
    status: 'error',
    message: message,
    ...(isDevelopment && { stack: err.stack })
  });
});

// 8. Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// 9. Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// 10. Server startup with environment validation
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (!process.env.NODE_ENV) {
  console.warn('WARNING: NODE_ENV not set, defaulting to development');
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);

  if (NODE_ENV !== 'production') {
    console.warn('Running in development mode. Set NODE_ENV=production for production use.');
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
EOF
